import {Chess} from './chess.js';
import {describeMove,moveStory} from './move-language.js';
const DAY=86400000;
export function matchingPractice(game,task){const p=game.training?.[task.index];return p?.fen===game.positions[task.index]&&p.bestUci===task.best?.uci?p:null}
export function practiceDueAt(p){if(!p)return 0;if(Number.isFinite(p.nextReviewAt))return p.nextReviewAt;return p.solved&&!p.revealed?(Number(p.updatedAt)||0)+DAY:0}
export function practiceQueue(game,tasks,now=Date.now(),force=false){return tasks.map(t=>({...t,progress:matchingPractice(game,t)})).filter(t=>force||practiceDueAt(t.progress)<=now).sort((a,b)=>{const rank=p=>!p?2:p.lastResult==='failed'||!p.solved&&!p.revealed?0:p.lastResult==='assisted'||p.revealed&&!p.streak?1:3;return rank(a.progress)-rank(b.progress)||practiceDueAt(a.progress)-practiceDueAt(b.progress)||b.loss-a.loss||a.index-b.index}).slice(0,3)}
export function recordPractice(previous,identity,result,{hintUsed=false,now=Date.now()}={}){const p=previous?.fen===identity.fen&&previous?.bestUci===identity.bestUci?previous:null;const independent=result==='solved'&&!hintUsed;const streak=independent?Math.min(4,(Number(p?.streak)||0)+1):0;const interval=independent?[1,3,7,14][streak-1]*DAY:result==='failed'?0:15*60000;return {...identity,attempts:(Number(p?.attempts)||0)+(result==='revealed'?0:1),solved:!!p?.solved||result==='solved',revealed:!!p?.revealed||result==='revealed',lastResult:independent?'solved':result==='failed'?'failed':'assisted',streak,nextReviewAt:now+interval,updatedAt:now};}
export function practiceReply(fen,attemptUci,replyUci){try{const b=new Chess(fen),attempt=b.move(attemptUci),after=b.fen(),reply=b.move(replyUci);let text='Один ответ соперника: '+describeMove(after,replyUci);if(b.isCheckmate())text+=' Ваш ход допускает этот мат в один ход.';else if(reply.captured){const takeBack=b.moves({verbose:true}).some(m=>m.to===reply.to&&m.captured);text+=takeBack?' На это взятие есть ответное взятие; размен нужно оценивать целиком.':'Немедленного ответного взятия этой фигуры на том же поле нет. Это ещё не исключает компенсацию другими способами.';}else{const idea=moveStory(after,replyUci).idea;text+=' '+(idea||'Этот ответ легален и выбран текущим расчётом. Сам по себе он ещё не объясняет всю разницу оценки.');}return {fen:b.fen(),attemptSan:attempt.san,replySan:reply.san,from:reply.from,to:reply.to,knight:reply.piece==='n',text};}catch{return null}}
